import * as THREE from 'three/webgpu';
import { color, mix, positionLocal, clamp } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  container.position.set(0, 0, 0);
  container.rotation.set(0, 0, 0);
  container.scale.set(1, 1, 1);

  // Extract colors from config
  const colorCfg = config.visual?.colors || {};
  const surfaceColor = new THREE.Color(colorCfg.surface || '#14141a');
  const accentColor = new THREE.Color(colorCfg.accent || '#ff2a38');
  const gradColor1 = new THREE.Color(
    colorCfg.gradientStops?.[0]?.hex || '#101017'
  );
  const gradColor2 = new THREE.Color(
    colorCfg.gradientStops?.[1]?.hex || '#1a1a22'
  );

  // Layout parameters
  const CELL_DEPTH = 0.06;
  const CELL_PADDING = 0.5;
  const GUTTER = 0.25;

  // Cell configuration: name, position, size, text content
  const cellDefs = [
    {
      name: 'dominant',
      x: -1.125,
      y: 0,
      width: 3.25,
      height: 3.5,
      valueText: '0.002 mm',
      valueSize: 124,
      labelText: 'Case tolerance, CNC pass',
      labelSize: 18
    },
    {
      name: 'secondary-top',
      x: 1.75,
      y: 0.9375,
      width: 2.0,
      height: 1.625,
      valueText: '38 h',
      valueSize: 68,
      labelText: 'Power reserve, NA-01',
      labelSize: 18
    },
    {
      name: 'secondary-bottom',
      x: 1.75,
      y: -0.9375,
      width: 2.0,
      height: 1.625,
      valueText: '214',
      valueSize: 68,
      labelText: 'Components per calibre',
      labelSize: 18
    }
  ];

  const animTargets = [];
  const timelines = [];

  // Create each cell
  cellDefs.forEach((cellDef, idx) => {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(cellDef.x, cellDef.y, 0);
    cellGroup.userData.cellIndex = idx;

    // Main cell slab with extruded geometry
    const slabGeo = new THREE.BoxGeometry(
      cellDef.width,
      cellDef.height,
      CELL_DEPTH
    );

    // Create diagonal gradient material using TSL
    // 135-degree gradient: from lower-right to upper-left
    const gradientNode = mix(
      color(gradColor1),
      color(gradColor2),
      clamp(
        (positionLocal.y.sub(positionLocal.x)).mul(0.35).add(0.5),
        0.0,
        1.0
      )
    );

    const slabMat = new THREE.MeshStandardNodeMaterial({
      colorNode: gradientNode,
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2
    });

    const slabMesh = new THREE.Mesh(slabGeo, slabMat);
    cellGroup.add(slabMesh);

    // Red accent tick bar (top-left, inside padding)
    const tickGeo = new THREE.BoxGeometry(0.4, 0.05, 0.08);
    const tickMat = new THREE.MeshStandardNodeMaterial({
      color: accentColor,
      emissive: accentColor,
      emissiveIntensity: 1.3
    });
    const tickMesh = new THREE.Mesh(tickGeo, tickMat);
    const tickX = -cellDef.width / 2 + CELL_PADDING + 0.2;
    const tickY = cellDef.height / 2 - CELL_PADDING - 0.025;
    tickMesh.position.set(tickX, tickY, CELL_DEPTH / 2 + 0.01);
    cellGroup.add(tickMesh);

    // Render text content via ctx.fontAtlas
    if (ctx.fontAtlas) {
      // Value text
      const valueMesh = ctx.fontAtlas.render(cellDef.valueText, cellDef.valueSize);
      if (valueMesh) {
        valueMesh.position.y = 0.15;
        valueMesh.position.z = CELL_DEPTH / 2 + 0.02;
        cellGroup.add(valueMesh);
      }

      // Label text
      const labelMesh = ctx.fontAtlas.render(cellDef.labelText, cellDef.labelSize);
      if (labelMesh) {
        labelMesh.position.y = -0.35;
        labelMesh.position.z = CELL_DEPTH / 2 + 0.02;
        cellGroup.add(labelMesh);
      }
    }

    container.add(cellGroup);
    animTargets.push({
      group: cellGroup,
      mesh: slabMesh,
      idx: idx,
      baseY: cellDef.y
    });
  });

  // Add header caption above grid
  if (ctx.fontAtlas) {
    const headerMesh = ctx.fontAtlas.render('ATELIER METRICS / Q2 2026', 18);
    if (headerMesh) {
      headerMesh.position.set(-2.75, 2.25, 0);
      container.add(headerMesh);
    }
  }

  // Entrance animation: stagger-cards with fade-up
  // y +0.2 to 0, 500ms ease, 80ms stagger per cell
  animTargets.forEach(({ group, idx, baseY }) => {
    group.position.y = baseY + 0.2;

    const tl = gsap.timeline({ delay: idx * 0.08 });

    tl.to(
      group.position,
      {
        y: baseY,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      },
      0
    );

    timelines.push(tl);
  });

  // Event handlers for hover interactions
  container.userData.handlers = {
    // Press-down: scale to 0.97 in 120ms
    onCellPointerEnter: (cellIndex) => {
      if (cellIndex >= 0 && cellIndex < animTargets.length) {
        const { group } = animTargets[cellIndex];
        gsap.to(
          group.scale,
          {
            x: 0.97,
            y: 0.97,
            z: 0.97,
            duration: 0.12,
            ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
            overwrite: 'auto'
          }
        );
      }
    },
    // Weighted-settle: overshoot 1.04 then settle to 1.0
    onCellPointerLeave: (cellIndex) => {
      if (cellIndex >= 0 && cellIndex < animTargets.length) {
        const { group } = animTargets[cellIndex];

        // Overshoot phase
        gsap.to(
          group.scale,
          {
            x: 1.04,
            y: 1.04,
            z: 1.04,
            duration: 0.12,
            ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
            overwrite: 'auto'
          }
        );

        // Settle phase
        gsap.to(
          group.scale,
          {
            x: 1.0,
            y: 1.0,
            z: 1.0,
            duration: 0.9,
            ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
            delay: 0.12,
            overwrite: 'auto'
          }
        );
      }
    }
  };

  // Cleanup: dispose all resources and kill animations
  container.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    animTargets.forEach(({ mesh }) => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });
  };

  return container;
}
